#include <Arduino.h>

// =====================================
// MOTOR SETTINGS
// =====================================

const float STEP_ANGLE_DEG = 1.8f;

const int STEPS_PER_REV =
    (int)(360.0f / STEP_ANGLE_DEG + 0.5f);

const uint8_t MOTOR_PINS[4] = {8, 9, 10, 11};
const uint8_t POT_PIN = A0;
const uint8_t BUTTON_PIN = 2;
const uint8_t DEBUG_PIN = 13;

const int SEQ_LEN = 4;
const int NUM_PINS = 4;

// Bipolar Full-Step sequence
const uint8_t STEP_SEQ[SEQ_LEN][NUM_PINS] = {
  {HIGH, LOW,  HIGH, LOW },
  {LOW,  HIGH, HIGH, LOW },
  {LOW,  HIGH, LOW,  HIGH},
  {HIGH, LOW,  LOW,  HIGH}
};

// =====================================
// TIMING
// =====================================

const unsigned int MIN_DELAY_MS = 2;
const unsigned int MAX_DELAY_MS = 20;
const unsigned int FIXED_DELAY_MS = 20;

const unsigned long PAUSE_MS = 1000;
const unsigned long DEBOUNCE_MS = 50;

const int ADC_MAX = 1023;

// true  = fixed 20ms speed (debug test)
// false = potentiometer controls 2-20ms
const bool TEST_FIXED_SPEED = true;

// =====================================
// MOTOR STATE
// =====================================

enum MotionState {
  RUN_CW,
  PAUSE_AFTER_CW,
  RUN_CCW
};

MotionState state = RUN_CW;

int stepIndex = 0;
int stepsDone = 0;

// Pressing button toggles manual reversal
bool manualReverse = false;

unsigned long lastStepTime = 0;
unsigned long pauseStartTime = 0;

// =====================================
// BUTTON DEBOUNCE
// =====================================

bool lastButtonReading = HIGH;
bool stableButtonState = HIGH;
unsigned long lastDebounceTime = 0;

void checkButton() {
  bool reading = digitalRead(BUTTON_PIN);
  unsigned long now = millis();

  if (reading != lastButtonReading) {
    lastDebounceTime = now;
  }

  if ((now - lastDebounceTime) >= DEBOUNCE_MS) {

    if (reading != stableButtonState) {
      stableButtonState = reading;

      // Active-low: only register a press
      if (stableButtonState == LOW) {
        manualReverse = !manualReverse;

        // Start counting a full revolution
        // from the reversal point
        if (state != PAUSE_AFTER_CW) {
          stepsDone = 0;
        }
      }
    }
  }

  lastButtonReading = reading;
}

// =====================================
// STEP SEQUENCE
// =====================================

void applyStep(int index) {
  for (int i = 0; i < NUM_PINS; i++) {
    digitalWrite(
      MOTOR_PINS[i],
      STEP_SEQ[index][i]
    );
  }
}

// =====================================
// SPEED CONTROL
// =====================================

unsigned int getStepDelay() {

  if (TEST_FIXED_SPEED) {
    return FIXED_DELAY_MS;
  }

  int potValue = analogRead(POT_PIN);

  return (unsigned int)map(
    potValue,
    0,
    ADC_MAX,
    MAX_DELAY_MS,
    MIN_DELAY_MS
  );
}

// =====================================
// DIRECTION
// =====================================

int getDirection() {

  int direction =
      (state == RUN_CCW) ? -1 : 1;

  if (manualReverse) {
    direction = -direction;
  }

  return direction;
}

// =====================================
// EXECUTE ONE STEP
// =====================================

void motorStep(int direction) {

  if (direction > 0) {
    stepIndex = (stepIndex + 1) % SEQ_LEN;
  } else {
    stepIndex =
        (stepIndex + SEQ_LEN - 1) % SEQ_LEN;
  }

  applyStep(stepIndex);

  // Show actual commanded direction
  // IO13 = 0: positive direction
  // IO13 = 1: negative direction
  digitalWrite(
    DEBUG_PIN,
    direction < 0 ? HIGH : LOW
  );
}

// =====================================
// SETUP
// =====================================

void setup() {

  for (int i = 0; i < NUM_PINS; i++) {
    pinMode(MOTOR_PINS[i], OUTPUT);
    digitalWrite(MOTOR_PINS[i], LOW);
  }

  pinMode(POT_PIN, INPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(DEBUG_PIN, OUTPUT);

  lastButtonReading = digitalRead(BUTTON_PIN);
  stableButtonState = lastButtonReading;

  digitalWrite(DEBUG_PIN, LOW);

  stepIndex = 0;
  stepsDone = 0;
  state = RUN_CW;
  manualReverse = false;

  applyStep(stepIndex);

  lastStepTime = millis() - FIXED_DELAY_MS;
}

// =====================================
// MAIN LOOP
// =====================================

void loop() {

  // Always check button
  checkButton();

  unsigned long now = millis();

  // -------- One second pause --------
  if (state == PAUSE_AFTER_CW) {

    if (now - pauseStartTime >= PAUSE_MS) {

      state = RUN_CCW;
      stepsDone = 0;

      lastStepTime = now - getStepDelay();
    }

    return;
  }

  // -------- Step timing --------
  unsigned int interval = getStepDelay();

  if (now - lastStepTime < interval) {
    return;
  }

  lastStepTime = now;

  // -------- Run motor --------
  int direction = getDirection();

  motorStep(direction);
  stepsDone++;

  // -------- Complete revolution --------
  if (stepsDone >= STEPS_PER_REV) {

    stepsDone = 0;

    if (state == RUN_CW) {

      state = PAUSE_AFTER_CW;
      pauseStartTime = now;

    } else if (state == RUN_CCW) {

      // Automatically repeat clockwise
      state = RUN_CW;
    }
  }
}
